INSERT INTO `interview_logs` (`id`, `nama_bumdesa`, `nama_narasumber`, `jabatan`, `transkrip_kapasitas_x1`, `transkrip_budaya_x2`, `transkrip_tata_kelola_x3`, `transkrip_pelaporan_y`, `created_at`, `updated_at`) VALUES
('2', 'SEGER SANTOSA', 'Faris Syaiful Hidayat', 'Direktur', 'Direktur BUMDesa menyampaikan bahwa ia bukan dari latar belakang akuntan sehingga harus belajar \"mulai dari nol\". Hal ini menjadi hambatan mendasar dalam pemahaman akun-akun keuangan.\r\nKendala utama yang dihadapi adalah kesulitan menginput dan mengklasifikasikan akun. Sebagai contoh, pengelola bingung menentukan pos pengeluaran untuk biaya rutin seperti listrik dan Wi-Fi, hingga menyebabkan sistem mendeteksi error (\"berwarna merah\" atau tidak balance). Meskipun sebelumnya telah menggunakan template Excel dari pendampingan STAN, direktur menilai bahwa aplikasi baru lebih sederhana, namun tetap membutuhkan pendampingan dalam penggunaannya.\r\nSelain itu, pencatatan keuangan masih dilakukan secara sederhana berupa pembukuan keluar masuk uang saja, serta dilakukan secara periodik setiap bulan. Hal ini menunjukkan bahwa kapasitas SDM masih terbatas dalam menerapkan sistem akuntansi yang lebih kompleks.', 'Secara formal, tidak ada paksaan personal. Namun, terdapat tuntutan formalitas dari program Dinas Sosial yang mengarahkan penyaluran kredit permodalan kepada masyarakat berdasarkan data penerima yang telah ditetapkan. BUMDes menyalurkan dana sekitar Rp60 juta kepada 25 orang penerima sesuai daftar yang diberikan.\r\nDampak dari kedekatan relasional di desa sangat nyata ketika kredit tersebut macet (hampir Rp40 juta tidak kembali). Ketika pihak BUMDesa mengirimkan surat tagihan kepada debitur yang juga merupakan tetangga sendiri. hubungan sosial antar warga yang sebelumnya baik menjadi kurang harmonis.', 'orang yang menerima uang, yang mencatat transaksi, sekaligus yang melaporkan adalah satu orang yang sama (bendahara). Sementara fungsi pemeriksaan langsung ke Kepala Desa. Secara pencatatan riil kas keluar-masuk, sudah sesuai dengan kondisi lapangan. Namun, laporan harus melalui proses penyesuaian/revisi yang dipandu oleh pendamping karena terdapat ketidaksesuaian (gap) di mana nominal angka yang diinput ke dalam sistem aplikasi berbeda dengan angka yang tercantum pada dokumen PDF laporan formal (Neraca, Laba Rugi, Ekuitas). Untuk laporannya selesai tepat waktu.', 'Direktur BUMDes menyampaikan bahwa laporan keuangan disusun secara rutin dan disampaikan tepat waktu kepada pemerintah desa dan BPD setiap akhir periode.\r\nPencatatan yang dilakukan dianggap sudah sesuai dengan kondisi riil transaksi di lapangan, meskipun terdapat penyesuaian teknis dalam penggunaan aplikasi. Secara umum, laporan keuangan masih mencerminkan aktivitas keuangan BUMDes.\r\nPendampingan yang paling dibutuhkan adalah bimbingan teknis secara berkelanjutan dalam penggunaan aplikasi keuangan digital, terutama dalam hal pengklasifikasian akun-akun keuangan yang sesuai dengan transaksi nyata di lapangan. Sebagai pengguna aplikasi yang bukan berlatar belakang akuntansi, membutuhkan pendamping yang dapat menjelaskan cara input data secara praktis dan sesuai kondisi BUMDesa.', '2026-06-07 15:21:07', '2026-06-07 15:21:07'),
('3', 'Sumber makmur kupang', 'Kusnul', 'Direktur', 'Informan menyampaikan bahwa latar belakang pendidikannya adalah SMA sehingga pemahaman terkait pencatatan dan penyusunan laporan keuangan masih terbatas. Penyusunan laporan keuangan BUMDesa saat ini lebih banyak dilakukan oleh sekretaris, sehingga informan masih memerlukan pelatihan untuk meningkatkan pemahaman di bidang tersebut.\r\n\r\nDalam penerapan aplikasi keuangan digital, kendala utama yang dihadapi adalah proses adaptasi terhadap aplikasi baru yang membutuhkan waktu untuk dipelajari.\r\n\r\nTerkait konsistensi pencatatan keuangan, hingga saat ini belum terdapat kendala yang berarti karena sistem pencatatan baru berjalan sekitar satu tahun dan setiap akhir bulan selalu dilakukan rekapitulasi sehingga pencatatan keuangan tetap terkelola dengan baik dan tidak terbengkalai.', 'Informan menjelaskan bahwa hubungan kekeluargaan dan kedekatan sosial di tingkat desa tidak menjadi hambatan dalam menjalankan pengelolaan keuangan BUMDesa secara profesional. Penegakan aturan bisnis tetap dilakukan secara tegas, termasuk terhadap pelanggan yang menunggak pembayaran layanan Wi-Fi, yang akan dikenakan sanksi berupa pemutusan jaringan internet sesuai ketentuan yang berlaku.\r\n\r\nInforman juga menyampaikan bahwa tidak pernah terjadi transaksi keuangan yang dilakukan atas dasar tekanan sosial atau keputusan informal tanpa bukti tertulis, karena seluruh keputusan mengikuti arahan direktur BUMDesa serta ketentuan dari pemerintah desa.\r\n\r\nDalam hal pengawasan, rasa sungkan terhadap sesama warga tidak menjadi kendala karena informan mampu memisahkan urusan pribadi dengan pekerjaan. Oleh karena itu, apabila ditemukan kesalahan administrasi atau pencatatan keuangan, informan tetap memberikan teguran dan melakukan koreksi sebagaimana mestinya demi menjaga ketertiban administrasi keuangan BUMDesa.', 'Informan menjelaskan bahwa pembagian tugas dalam pengelolaan keuangan BUMDesa sebenarnya telah dilakukan dengan jelas, yaitu tugas penyimpanan keuangan dilakukan oleh bendahara, pencatatan dilakukan oleh sekretaris, dan pemeriksaan dilakukan oleh direktur. Namun demikian, kendala yang masih dihadapi adalah keterbatasan kualitas sumber daya manusia karena sebagian besar pengurus hanya berlatar belakang pendidikan SMA sehingga kemampuan teknis dalam pengelolaan dan pelaporan keuangan masih perlu ditingkatkan.\r\n\r\nMeskipun terdapat berbagai keterbatasan, laporan keuangan tetap dapat diselesaikan tepat waktu melalui pencatatan yang dilakukan secara rutin setiap bulan, pembagian tugas yang jelas antar pengurus, serta adanya pengawasan dan evaluasi bersama yang melibatkan kepala desa', 'Informan juga menegaskan bahwa laporan keuangan yang disusun telah mencerminkan kondisi riil di lapangan karena seluruh transaksi dicatat berdasarkan bukti dan kegiatan usaha yang benar-benar terjadi, sehingga tidak dilakukan penyesuaian khusus hanya untuk memenuhi tuntutan administratif atau formalitas birokrasi.\r\n\r\nInforman menilai bahwa pendampingan dari akademisi maupun dinas terkait sangat diperlukan, terutama dalam bentuk pelatihan, bimbingan teknis, dan konsultasi berkelanjutan mengenai pengelolaan serta pelaporan keuangan. Pendampingan tersebut diharapkan dapat meningkatkan kompetensi pengurus BUMDesa, memperkuat penerapan prinsip akuntabilitas, serta memastikan laporan keuangan yang disusun tidak hanya memenuhi kewajiban administratif, tetapi juga menjadi alat pertanggungjawaban yang transparan dan dapat dipercaya.', '2026-06-08 05:17:47', '2026-06-08 05:17:47');
